<?php require_once 'includes.php';page_header('Find group trips');$w=["trip_type='group'","status='open'","travel_date>=CURDATE()"];$p=[];$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$date=(string)($_GET['date']??'');if($from!==''){$w[]='from_city LIKE ?';$p[]="%$from%";}if($to!==''){$w[]='to_place LIKE ?';$p[]="%$to%";}if($date!==''&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){$w[]='travel_date=?';$p[]=$date;}$s=db()->prepare('SELECT t.*,u.name host_name FROM trips t JOIN users u ON u.id=t.host_id WHERE '.implode(' AND ',$w).' ORDER BY travel_date');$s->execute($p);$trips=$s->fetchAll();?><section class="page-intro"><p class="eyebrow">TRAVEL BETTER, TOGETHER</p><h1>Find your next group trip</h1><p>Compare routes and request to join a trip that matches your interests.</p></section><div class="page-wrap"><form class="filters-row panel"><label class="form-field">From<input name="from" value="<?=e($from)?>" placeholder="Starting city"></label><label class="form-field">To<input name="to" value="<?=e($to)?>" placeholder="Destination"></label><label class="form-field">Date<input name="date" type="date" value="<?=e($date)?>"></label><button class="btn btn-primary">Search</button><a class="btn btn-light" href="group-trips.php">Clear</a></form><div class="section-heading"><div><h2>Upcoming trips</h2><p><?=count($trips)?> trips found</p></div><a class="btn btn-primary" href="create-trip.php">+ Create trip</a></div><?php if(!$trips):?><div class="empty-state"><h3>No matching group trips yet</h3><p>Try another route or publish your own idea.</p></div><?php else:?><div class="trip-list"><?php foreach($trips as $t):?><article class="trip-card"><div><span class="pill"><?=e(ucfirst($t['travel_style']))?> · <?= (int)$t['duration_days']?> day(s)</span><h3 style="margin-top:12px"><?=e($t['title'])?></h3><p class="trip-meta"><?=e($t['from_city'])?> → <?=e($t['to_place'])?> · <?=e(date('d M Y',strtotime($t['travel_date'])))?> · <?= (int)$t['seats_available']?> seats · Host <?=e($t['host_name'])?></p><p><?=e(mb_strimwidth((string)$t['description'],0,180,'…'))?></p></div><div><div class="price">₹<?=number_format((float)$t['estimated_cost'])?> / person</div><a class="btn btn-primary" href="trip.php?id=<?=(int)$t['id']?>">View trip</a></div></article><?php endforeach;?></div><?php endif;?></div><?php page_footer();?>